SELECT t.id as id, t.code as contractCode, t.frame_agreement_id as agreementId, t.total_number as totalNumber, t.re_month as reMonth, t.total_number as totalNumber, t.re_merge_state as reMergeState, t.re_remark as reRemark FROM sales_contract t where t.deleted = 0 and t.frame_agreement_id in
#{id}
order by t.agreement_date

SELECT id AS id, disabled AS disabled, name AS contractName, code AS contractCode, sales_org_id AS orgId, sales_org_name AS orgName, contract_type AS contractType, customer_id AS customerId, customer_name AS customerName, tray_customer_id AS trayCustomerId, tray_customer_name AS trayCustomerName, signed_time AS signedTime, effective_time AS effectiveTime, end_time AS endTime, department AS department, salesman AS salesman, price_type AS priceType, frame_agreement_id AS agreementId, case when frame_agreement_id is not null then frame_agreement_code else nc_agreement_code end AS agreementCode, agreement_date AS agreementDate, bear_cost_type AS bearCostType, departure_place AS departurePlace, whole_measurement AS wholeMeasurement, ocean_customers AS oceanCustomers, total_number AS totalNumber, total_price_tax AS totalPriceTax, pound_note AS poundNote, remark AS remark, contract_version AS contractVersion, busi_source AS busiSource, create_time AS createTime, create_name AS createName, system_source AS systemSource FROM sales_contract c WHERE deleted = 0
AND (name = #{param.contractNameCode} OR code = #{param.contractNameCode})
AND customer_uscc = #{param.customerUscc}
AND org_uscc = #{param.orgUscc}
AND disabled = #{param.disabled}
AND departure_place = #{param.departurePlace}
AND create_time >= #{param.createTimeStart}
AND create_time <= #{param.createTimeEnd}
AND (salesman = #{param.userName} OR create_name = #{param.userName})
AND bear_cost_type IN
#{item}
AND whole_measurement = #{param.wholeMeasurement}
AND ocean_customers = #{param.oceanCustomers}
AND busi_source IN
#{item}
order by c.disabled,create_time desc
